import { createEffect, createSignal, mergeProps, type ParentComponent } from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { Activatable, ActivatableProps } from "./activatable";

export interface ButtonProps extends ActivatableProps {
	size?: "standard" | "small";
}
const ButtonComponent: ParentComponent<ButtonProps> = (props) => {
	const [mergedProps, setMergedProps] = createSignal<ButtonProps>({ size: "standard" });

	createEffect(() => {
		const audioObject = props.audio ?? {};
		audioObject.onPress ??= "data-audio-primary-button-press";
		audioObject.onFocus ??= "data-audio-primary-button-focus";

		const defaultProps: ButtonProps = { audio: audioObject, size: "standard" };
		const finalPropsObject = mergeProps(defaultProps, props);

		setMergedProps(finalPropsObject);
	});

	return (
		<Activatable
			{...mergedProps()}
			class={`fxs-button relative flex min-h-11\\.5" items-center justify-center font-title text-base text-accent-1 uppercase tracking-150 text-shadow-subtle leading-none text-center ${
				props.class ?? ""
			}`}
			classList={{
				"px-4 py-1": mergedProps().size == "standard",
				"px-3 fxs-button-small": mergedProps().size == "small",
			}}
			name="Button"
		>
			<div class="absolute inset-0">
				<div class="absolute inset-0 fxs-button__bg fxs-button__bg--base" />
				<div class="absolute inset-0 opacity-0 fxs-button__bg fxs-button__bg--focus" />
				<div class="absolute inset-0 opacity-0 fxs-button__bg fxs-button__bg--active" />
				<div class="absolute inset-0 opacity-0 fxs-button__bg fxs-button__bg--disabled" />
			</div>
			{/* Putting the contents in an inner div, prevents weird text layout bugs for some reason */}
			<div class="relative flex flex-auto items-center justify-center">{props.children}</div>
		</Activatable>
	);
};

/**
 * A Button component.
 * A simple activatable button.
 * ```tsx
 * // Example - Simple button
 * <Button onActivate={() => console.log("activated")}>Click Me!</Button>
 * ```
 * Default implementation: {@link ButtonComponent} Based on: {@link Activatable}
 * @param {ActivatableProps} props See {@link ActivatableProps} for a full list of properties
 *
 * Commonly Used Properties:
 * @param {boolean} props.disabled Is this control disabled both visually and for input? Default: false
 * @param {string} props.hotkeyAction The name of a hotkey action which activates this component. Default: undefined
 * @param {string} props.name The name of the component set as the data-name property - useful for debugging or searching the DOM tree. Default: "Activatable"
 * @param {() => void} props.onActivate Event which triggers when the control is activated either through hotkey, mouse click, touch, or other user interaction. Default: undefined
 */
export const Button = ComponentRegistry.register({
	name: "Button",
	createInstance: ButtonComponent,
	images: [
		"blp:base_button-bg.png",
		"blp:base_button-bg-focus.png",
		"blp:base_button-bg-press.png",
		"blp:base_button-bg-dis.png",
	],
});
